import bpy, bmesh, math, random, traceback
from mathutils import Vector, Matrix

SC = bpy.context.scene
KIT = ('Kit_Camere', 'Kit_Abitanti', 'Kit_Animali', 'Kit_Percorsi', 'Kit_Luci')
WALK = ('Terreno', 'Strade_Rurali', 'Strade_Borgo', 'Ponte', 'Ponticelli', 'Ponti_Nuovi')
LOG = []

def log(msg):
    LOG.append(str(msg)); print(msg)
    t = bpy.data.texts.get('Kit_Log') or bpy.data.texts.new('Kit_Log')
    t.clear(); t.write('\n'.join(LOG))

def B(x, y, z):
    return Vector((x, -z, y))

def fcurves_of(idb):
    ad = getattr(idb, 'animation_data', None)
    if not ad or not ad.action:
        return []
    try:
        return list(ad.action.fcurves)
    except Exception:
        pass
    out = []
    for layer in getattr(ad.action, 'layers', []):
        for strip in layer.strips:
            for cb in getattr(strip, 'channelbags', []):
                out += list(cb.fcurves)
    return out

def interp(idb, tipo):
    for fc in fcurves_of(idb):
        for k in fc.keyframe_points:
            k.interpolation = tipo

def collezione(nome):
    c = bpy.data.collections.get(nome)
    if c is None:
        c = bpy.data.collections.new(nome); SC.collection.children.link(c)
    return c

def pulisci():
    for nome in KIT:
        c = bpy.data.collections.get(nome)
        if c:
            for ob in list(c.objects):
                bpy.data.objects.remove(ob, do_unlink=True)
    nomi = {r['nome'] for r in DATI['riprese'] + DATI.get('riprese_nuove', [])} | {'07_Sentieri'}
    for m in list(SC.timeline_markers):
        if m.name in nomi:
            SC.timeline_markers.remove(m)
    for me in list(bpy.data.meshes):
        if me.get('kit') and me.users == 0:
            bpy.data.meshes.remove(me)
    for ob in bpy.data.objects:
        if ob.name.startswith('Mare'):
            for m in list(ob.modifiers):
                if m.name == 'Onde':
                    ob.modifiers.remove(m)

def modello():
    if any(o.name.startswith('Terreno') for o in bpy.data.objects):
        return
    if PERCORSO_OBJ:
        bpy.ops.wm.obj_import(filepath=PERCORSO_OBJ); return
    raise RuntimeError("Importa prima castello_mappa_estesa.obj (File > Import > Wavefront) oppure scrivi il percorso in PERCORSO_OBJ")

def quota(x, z, nomi=WALK):
    """quota della prima superficie calpestabile sotto il punto (terreno, strade, ponti)"""
    dg = bpy.context.evaluated_depsgraph_get()
    o = Vector((x, -z, 3000.0)); d = Vector((0.0, 0.0, -1.0))
    for _ in range(80):
        hit, loc, nor, idx, ob, mw = SC.ray_cast(dg, o, d)
        if not hit:
            return None
        if ob.name.startswith(nomi):
            return loc.z
        o = loc + d * 0.02
    return None

def punto(p):
    x, z, h, modo = p
    if modo == 'a':
        return B(x, h, z)
    q = quota(x, z, ('Mura',) if modo == 'm' else WALK)
    return Vector((x, -z, (q if q is not None else 0.0) + h))

def curva(nome, punti, coll, chiusa=False):
    cu = bpy.data.curves.new(nome, 'CURVE'); cu.dimensions = '3D'; cu.use_path = True
    sp = cu.splines.new('NURBS'); sp.points.add(len(punti) - 1)
    for i, p in enumerate(punti):
        sp.points[i].co = (p.x, p.y, p.z, 1.0)
    sp.order_u = min(4, len(punti)); sp.use_cyclic_u = chiusa; sp.use_endpoint_u = not chiusa
    ob = bpy.data.objects.new(nome, cu); coll.objects.link(ob); ob.hide_render = True
    return ob

def segui(ob, cur, f0, f1):
    c = ob.constraints.new('FOLLOW_PATH'); c.target = cur; c.use_fixed_location = True
    c.offset_factor = 0.0; c.keyframe_insert('offset_factor', frame=f0)
    c.offset_factor = 1.0; c.keyframe_insert('offset_factor', frame=f1)

# --------------------------------------------------------------- materiali e texture
def materiali_mappa():
    usati = set()
    for ob in bpy.data.objects:
        if ob.type == 'MESH' and not any(ob.name in c.objects for c in [bpy.data.collections.get(k) for k in KIT] if c):
            for s in ob.material_slots:
                if s.material and not s.material.name.startswith('npc_'):
                    usati.add(s.material)
    return usati

FAM = {'pietra': ('wall_stone', 'tower_stone', 'stone_dark', 'stone_light', 'moss_stone', 'street_stone', 'piazza_stone', 'marble', 'terrain_rock', 'wall_brick'),
       'intonaco': ('wall_plaster', 'wall_plaster_ochre', 'wall_plaster_rose'),
       'tetto': ('roof_terracotta', 'roof_slate', 'roof_thatch', 'hay'),
       'legno': ('wood_trim', 'fence_wood', 'trunk_brown'),
       'terra': ('terrain_grass', 'terrain_meadow', 'terrain_forest', 'terrain_field', 'terrain_gravel', 'terrain_clay', 'soil_dark', 'path_dirt', 'sand'),
       'fogliame': ('tree_green', 'tree_light', 'tree_dark', 'tree_olive', 'tree_autumn', 'conifer', 'cypress', 'hedge', 'crop_green', 'crop_gold', 'vine', 'reed', 'lavender')}
PAR = {'pietra': (1.4, 0.20, 0.35), 'intonaco': (3.0, 0.07, 0.10), 'tetto': (2.4, 0.16, 0.30), 'legno': (3.0, 0.18, 0.20), 'terra': (0.12, 0.22, 0.12), 'fogliame': (0.8, 0.18, 0.22)}

def texture(m, fam):
    nt = m.node_tree; b = next((n for n in nt.nodes if n.type == 'BSDF_PRINCIPLED'), None)
    if b is None or b.inputs['Base Color'].is_linked:
        return False
    scala, contr, bump = PAR[fam]
    base = b.inputs['Base Color'].default_value
    tc = nt.nodes.new('ShaderNodeTexCoord')
    if fam == 'legno':
        tx = nt.nodes.new('ShaderNodeTexWave'); tx.inputs['Scale'].default_value = scala; tx.inputs['Distortion'].default_value = 4.0
        try: tx.bands_direction = 'Z'
        except Exception: pass
    else:
        tx = nt.nodes.new('ShaderNodeTexNoise'); tx.inputs['Scale'].default_value = scala; tx.inputs['Detail'].default_value = 5.0
    nt.links.new(tc.outputs['Object'], tx.inputs['Vector'])
    cr = nt.nodes.new('ShaderNodeValToRGB'); e = cr.color_ramp.elements
    e[0].position = 0.3; e[1].position = 0.7
    e[0].color = (base[0] * (1 - contr), base[1] * (1 - contr), base[2] * (1 - contr), 1.0)
    e[1].color = (min(1, base[0] * (1 + contr * 0.6)), min(1, base[1] * (1 + contr * 0.6)), min(1, base[2] * (1 + contr * 0.6)), 1.0)
    nt.links.new(tx.outputs['Fac'], cr.inputs['Fac']); nt.links.new(cr.outputs['Color'], b.inputs['Base Color'])
    if fam == 'pietra':
        vo = nt.nodes.new('ShaderNodeTexVoronoi'); vo.inputs['Scale'].default_value = scala * 1.8
        nt.links.new(tc.outputs['Object'], vo.inputs['Vector']); hsrc = vo.outputs['Distance']
    elif fam == 'terra':
        fine = nt.nodes.new('ShaderNodeTexNoise'); fine.inputs['Scale'].default_value = 3.0
        nt.links.new(tc.outputs['Object'], fine.inputs['Vector']); hsrc = fine.outputs['Fac']
    else:
        hsrc = tx.outputs['Fac']
    bu = nt.nodes.new('ShaderNodeBump'); bu.inputs['Strength'].default_value = bump
    try: bu.inputs['Distance'].default_value = 0.05
    except Exception: pass
    nt.links.new(hsrc, bu.inputs['Height'])
    if not b.inputs['Normal'].is_linked:
        nt.links.new(bu.outputs['Normal'], b.inputs['Normal'])
    return True

def migliora_materiali():
    nt_ = 0; tolte = 0
    for m in materiali_mappa():
        if not m.use_nodes or m.node_tree is None:
            continue
        b = next((n for n in m.node_tree.nodes if n.type == 'BSDF_PRINCIPLED'), None)
        if b is None:
            continue
        nome = m.name.split('.')[0]
        def s(k, v):
            if k in b.inputs:
                try: b.inputs[k].default_value = v
                except Exception: pass
        s('Roughness', 0.85); s('Specular IOR Level', 0.25)
        if nome in ('water', 'sea', 'water_deep'):
            s('Roughness', 0.04); s('IOR', 1.33); s('Specular IOR Level', 0.5)
            if nome != 'water_deep':
                s('Alpha', 0.82)
                for attr, val in (('surface_render_method', 'BLENDED'), ('blend_method', 'BLEND')):
                    try: setattr(m, attr, val); break
                    except Exception: pass
        elif nome in ('fire_glow', 'ember', 'magic_violet', 'crystal_teal'):
            s('Emission Color', b.inputs['Base Color'].default_value); s('Emission Strength', 2.0 if nome == 'crystal_teal' else 5.0)
        elif nome in ('iron_dark', 'bronze'):
            s('Metallic', 0.7); s('Roughness', 0.45)
        elif nome in ('window_dark', 'cave_dark'):
            s('Roughness', 0.95); s('Specular IOR Level', 0.0)
        if TEXTURE and not m.get('kit_texture'):
            for fam, nomi in FAM.items():
                if nome in nomi and texture(m, fam):
                    m['kit_texture'] = True; nt_ += 1; break
        elif not TEXTURE and m.get('kit_texture'):
            togli_texture(m); tolte += 1
    if TEXTURE:
        log('Materiali ritoccati; texture procedurali aggiunte a %d materiali' % nt_)
    else:
        log('Texture procedurali spente: tolte da %d materiali (colori pieni originali)' % tolte)

def togli_texture(m):
    """toglie i nodi aggiunti da texture(): il colore torna quello pieno del materiale"""
    nt = m.node_tree
    for n in [n for n in nt.nodes if n.type in ('TEX_COORD', 'TEX_NOISE', 'TEX_WAVE', 'TEX_VORONOI', 'VALTORGB', 'BUMP')]:
        nt.nodes.remove(n)
    if 'kit_texture' in m:
        del m['kit_texture']

def materiale(nome, col, rough=0.8):
    m = bpy.data.materials.get(nome) or bpy.data.materials.new(nome)
    m.use_nodes = True
    b = next(n for n in m.node_tree.nodes if n.type == 'BSDF_PRINCIPLED')
    b.inputs['Base Color'].default_value = (col[0], col[1], col[2], 1.0); b.inputs['Roughness'].default_value = rough
    m.diffuse_color = (col[0], col[1], col[2], 1.0)   # stesso colore anche nella vista Solida
    return m

# --------------------------------------------------------------- cielo a gradiente e sole fisso
def mondo():
    w = SC.world or bpy.data.worlds.new('Mondo'); SC.world = w; w.use_nodes = True
    for attr, val in (('sun_threshold', 0.0), ('use_sun_shadow', False)):
        try: setattr(w, attr, val)
        except Exception: pass
    nt = w.node_tree
    for n_ in list(nt.nodes):
        nt.nodes.remove(n_)
    out = nt.nodes.new('ShaderNodeOutputWorld'); bg = nt.nodes.new('ShaderNodeBackground')
    bg.inputs['Strength'].default_value = LUCE_CIELO
    tc = nt.nodes.new('ShaderNodeTexCoord'); sep = nt.nodes.new('ShaderNodeSeparateXYZ')
    cr = nt.nodes.new('ShaderNodeValToRGB'); e = cr.color_ramp.elements
    e[0].position = 0.5; e[1].position = 0.8
    e[0].color = (*COLORE_CIELO_ORIZZONTE, 1.0); e[1].color = (*COLORE_CIELO_ALTO, 1.0)
    nt.links.new(tc.outputs['Generated'], sep.inputs[0])
    mr = nt.nodes.new('ShaderNodeMapRange'); mr.inputs['From Min'].default_value = -1.0; mr.inputs['From Max'].default_value = 1.0
    nt.links.new(sep.outputs['Z'], mr.inputs['Value']); nt.links.new(mr.outputs['Result'], cr.inputs['Fac'])
    nt.links.new(cr.outputs['Color'], bg.inputs['Color']); nt.links.new(bg.outputs[0], out.inputs['Surface'])
    if NEBBIA:
        v = nt.nodes.new('ShaderNodeVolumePrincipled')
        v.inputs['Density'].default_value = 0.0008 if QUALITA == 'prova' else 0.0006
        v.inputs['Color'].default_value = (*COLORE_CIELO_ORIZZONTE, 1.0)
        nt.links.new(v.outputs[0], out.inputs['Volume'])

def sole(coll):
    el = math.radians(max(8.0, 62.0 * math.sin(math.pi * (ORA_DEL_SOLE - 6.0) / 12.0)))
    az = (ORA_DEL_SOLE - 18.0) * math.pi / 12.0
    d = Vector((math.cos(el) * math.cos(az), math.cos(el) * math.sin(az), math.sin(el)))
    ld = bpy.data.lights.new('Sole', 'SUN'); ld.energy = 4.0
    ld.color = (1.0, 0.88, 0.75) if math.degrees(el) < 20 else (1.0, 0.97, 0.92)
    for attr, val in (('angle', math.radians(0.6)), ('use_shadow_jitter', False), ('shadow_filter_radius', 1.5), ('shadow_maximum_resolution', 0.002)):
        try: setattr(ld, attr, val)
        except Exception: pass
    ob = bpy.data.objects.new('Sole', ld); coll.objects.link(ob)
    ob.rotation_euler = d.to_track_quat('Z', 'Y').to_euler()
    return ob

def qualita_ombre():
    ee = SC.eevee; ris = '1' if OMBRE_ALTA_QUALITA else '2'
    for obj, attr, val in ((ee, 'fast_gi_resolution', ris), (ee, 'fast_gi_ray_count', 4 if OMBRE_ALTA_QUALITA else 2),
                           (ee, 'use_shadow_jitter_viewport', False), (ee, 'use_volumetric_shadows', False),
                           (ee, 'volumetric_tile_size', '8'), (ee, 'volumetric_end', 1500.0)):
        try: setattr(obj, attr, val)
        except Exception: pass
    rt = getattr(ee, 'ray_tracing_options', None)
    if rt is not None:
        for attr, val in (('resolution_scale', ris), ('use_denoise', True)):
            try: setattr(rt, attr, val)
            except Exception: pass

# --------------------------------------------------------------- camere
def ripresa(r, f0, coll, pcoll):
    f1 = f0 + r['fotogrammi'] - 1
    cd = bpy.data.cameras.new(r['nome']); cd.lens = r['lente']; cd.clip_start = 0.2; cd.clip_end = 5000
    cam = bpy.data.objects.new(r['nome'], cd); coll.objects.link(cam)
    segui(cam, curva(r['nome'] + '_percorso', [punto(p) for p in r['punti']], pcoll), f0, f1)
    tg = bpy.data.objects.new(r['nome'] + '_bersaglio', None); coll.objects.link(tg); tg.empty_display_size = 0.3
    if isinstance(r['bersaglio'], list):
        segui(tg, curva(r['nome'] + '_percorso_bersaglio', [punto(p) for p in r['bersaglio']], pcoll), f0, f1)
    else:
        tg.location = punto(r['bersaglio'])
    t = cam.constraints.new('TRACK_TO'); t.target = tg; t.track_axis = 'TRACK_NEGATIVE_Z'; t.up_axis = 'UP_Y'
    cd.dof.use_dof = True; cd.dof.focus_object = tg; cd.dof.aperture_fstop = r['fstop']
    m = SC.timeline_markers.new(r['nome'], frame=f0); m.camera = cam
    return cam, f1

# --------------------------------------------------------------- persone e animali articolati (forme in MODELLI)
COLORI_BASE = {'fur_white': (0.92, 0.92, 0.9), 'fur_brown': (0.45, 0.28, 0.16), 'fur_black': (0.12, 0.11, 0.1), 'fur_tan': (0.72, 0.55, 0.36),
               'fur_grey': (0.52, 0.5, 0.48), 'feather_white': (0.95, 0.95, 0.93), 'wool_white': (0.9, 0.88, 0.82), 'beak_orange': (0.9, 0.55, 0.12),
               'stone_dark': (0.36, 0.35, 0.33), 'stone_light': (0.72, 0.69, 0.62), 'trunk_brown': (0.35, 0.24, 0.14), 'wall_plaster_rose': (0.86, 0.66, 0.6),
               'flag_red': (0.7, 0.12, 0.1), 'hedge': (0.18, 0.36, 0.16), 'wood_trim': (0.36, 0.24, 0.14), 'iron_dark': (0.25, 0.25, 0.27), 'hay': (0.8, 0.7, 0.4)}
_MESH = {}

def mat_mappa(nome):
    m = bpy.data.materials.get(nome) or next((x for x in bpy.data.materials if x.name.split('.')[0] == nome), None)
    return m or materiale(nome, COLORI_BASE.get(nome, (0.6, 0.6, 0.6)))

def mesh_parte(chiave, parte, mappa):
    """mesh condivisa fra tutti gli esemplari con la stessa forma e gli stessi colori"""
    k = (chiave, parte['nome'], tuple(sorted(mappa.items())))
    me = _MESH.get(k)
    if me is not None:
        return me
    me = bpy.data.meshes.new('npc_%s_%s' % (chiave, parte['nome']))
    me.from_pydata(parte['V'], [], parte['F'])
    nomi = []
    for t in parte['M']:
        n = mappa.get(t, t)
        if n not in nomi:
            nomi.append(n)
    for n in nomi:
        me.materials.append(mat_mappa(n))
    me.polygons.foreach_set('material_index', [nomi.index(mappa.get(t, t)) for t in parte['M']])
    me.update(); me['kit'] = True
    _MESH[k] = me
    return me

def rig(nome, chiave, mappa, coll):
    root = bpy.data.objects.new(nome, None); coll.objects.link(root); root.empty_display_size = 0.3
    obs = {}
    for p in MODELLI[chiave]:
        ob = bpy.data.objects.new(nome + '_' + p['nome'], mesh_parte(chiave, p, mappa)); coll.objects.link(ob)
        ob.parent = obs[p['genitore']] if p['genitore'] else root
        ob.location = p['perno']
        obs[p['nome']] = ob
    root['passo'] = 1.0
    return root, obs

def drv(ob, asse, espr, prop='rotation_euler', passo=None):
    fc = ob.driver_add(prop, asse); d = fc.driver; d.type = 'SCRIPTED'
    if passo is not None:
        v = d.variables.new(); v.name = 'p'; v.type = 'SINGLE_PROP'
        v.targets[0].id = passo; v.targets[0].data_path = '["passo"]'
    d.expression = espr
    return fc

def lunghezza(pts, chiusa=True):
    L = sum((b - a).length for a, b in zip(pts, pts[1:]))
    return L + ((pts[0] - pts[-1]).length if chiusa else 0)

def _percorso(root, cur):
    c = root.constraints.new('FOLLOW_PATH'); c.target = cur; c.use_fixed_location = True
    c.use_curve_follow = True; c.forward_axis = 'FORWARD_Y'; c.up_axis = 'UP_Z'
    # in salita e in discesa il corpo resta dritto: tengo solo la rotazione attorno alla verticale
    l = root.constraints.new('LIMIT_ROTATION'); l.owner_space = 'WORLD'
    l.use_limit_x = True; l.min_x = l.max_x = 0.0; l.use_limit_y = True; l.min_y = l.max_y = 0.0
    return c

def _chiavi(c, pts):
    """pts: [(fotogramma, posizione non avvolta)] -> chiavi di offset_factor con il giro 1 -> 0"""
    for (f0, p0), (f1, p1) in zip(pts, pts[1:]):
        c.offset_factor = p0 % 1.0; c.keyframe_insert('offset_factor', frame=f0)
        k = math.floor(p0) + 1
        while k <= p1 and p1 > p0:
            fk = f0 + (k - p0) / (p1 - p0) * (f1 - f0)
            c.offset_factor = 1.0; c.keyframe_insert('offset_factor', frame=fk - 0.01)
            c.offset_factor = 0.0; c.keyframe_insert('offset_factor', frame=fk)
            k += 1
    f1, p1 = pts[-1]; c.offset_factor = p1 % 1.0; c.keyframe_insert('offset_factor', frame=f1)

def cammina(root, cur, L, vel, fase, ftot):
    """cammino continuo (persone, uccelli in volo)"""
    c = _percorso(root, cur)
    P = max(30.0, L / max(vel, 0.05) * FPS); f0 = -P
    _chiavi(c, [(f0, fase), (ftot + P, fase + (ftot + 2 * P) / P)])
    interp(root, 'LINEAR')

def pascolo(root, cur, L, vel, fase, ftot, rnd, muovi=(4.0, 9.0), ferma=(3.0, 9.0)):
    """tratti di cammino alternati a soste: durante le soste le zampe si fermano (proprietà 'passo') e l'animale bruca o si guarda intorno"""
    c = _percorso(root, cur)
    ferma = (max(0.2, ferma[0] * SOSTE_ANIMALI), max(0.3, ferma[1] * SOSTE_ANIMALI))
    f = -rnd.uniform(0, 200); pos = fase; pts = [(f, pos)]; pk = []
    fermo = rnd.random() < 0.5; inizio = 0.0 if fermo else 1.0
    while f < ftot + 50:
        if fermo:
            f += rnd.uniform(*ferma) * FPS; pts.append((f, pos)); pk += [(f - 5, 0.0), (f + 5, 1.0)]
        else:
            T = rnd.uniform(*muovi) * FPS; pos += vel * T / FPS / max(L, 0.5); f += T; pts.append((f, pos)); pk += [(f - 5, 1.0), (f + 5, 0.0)]
        fermo = not fermo
    _chiavi(c, pts)
    root['passo'] = inizio; root.keyframe_insert('["passo"]', frame=pts[0][0])
    for fr, val in pk:
        root['passo'] = val; root.keyframe_insert('["passo"]', frame=fr)
    interp(root, 'LINEAR')

# parametri di andatura: velocità (m/s), lunghezza gamba (m), ampiezza (rad), bruca
ANDATURA = {'cow': (0.6, 0.93, 0.30, True), 'horse': (0.9, 1.17, 0.32, True), 'donkey': (0.6, 0.83, 0.32, True), 'sheep': (0.45, 0.51, 0.35, True),
            'goat': (0.55, 0.54, 0.35, True), 'pig': (0.45, 0.46, 0.35, False), 'deer': (0.75, 0.81, 0.32, True), 'dog': (1.0, 0.36, 0.40, False)}
ZAMPE4 = (('post_sx', 0.0), ('ant_sx', 0.5 * math.pi), ('post_dx', math.pi), ('ant_dx', 1.5 * math.pi))

def _w(v, l, A):
    return 2 * math.pi * v / (FPS * 4 * l * math.sin(A))

def anima_quadrupede(root, obs, sp, fase):
    v, l, A, bruca = ANDATURA[sp]; v *= VELOCITA_ANIMALI
    ph = 'frame*%.4f+%.3f' % (_w(v, l, A), fase)
    c = obs['corpo']; z0 = c.location.z
    drv(c, 2, '%.3f+p*0.018*abs(sin(%s))' % (z0, ph), prop='location', passo=root)
    drv(c, 1, 'p*0.025*sin(%s)' % ph, passo=root)
    k = obs['collo']
    if bruca:
        drv(k, 0, 'p*0.05*sin(2*(%s))-(1-p)*(0.45+0.35*max(0,sin(frame*0.013+%.3f)))' % (ph, fase * 1.7), passo=root)
    else:
        drv(k, 0, 'p*0.05*sin(2*(%s))-(1-p)*0.2*max(0,sin(frame*0.02+%.3f))' % (ph, fase), passo=root)
    drv(k, 2, '0.3*sin(frame*0.011+%.3f)*(1-0.6*p)' % (fase * 2.3), passo=root)
    if sp == 'dog':
        drv(obs['coda'], 2, '0.5*sin(frame*0.55+%.3f)' % fase)
    else:
        drv(obs['coda'], 1, '0.3*sin(frame*0.09+%.3f)+0.1*sin(frame*0.23+%.3f)' % (fase, fase * 1.3))
    for nome, o in ZAMPE4:
        drv(obs['zampa_' + nome], 0, 'p*%.3f*sin(%s+%.3f)' % (A, ph, o), passo=root)
        drv(obs['stinco_' + nome], 0, '-p*%.3f*max(0,cos(%s+%.3f))' % (A * 2.2, ph, o), passo=root)
    return v

def anima_gallina(root, obs, fase):
    vg = 0.35 * VELOCITA_ANIMALI
    ph = 'frame*%.4f+%.3f' % (_w(vg, 0.2, 0.5), fase)
    c = obs['corpo']
    drv(c, 2, '%.3f+p*0.012*abs(sin(%s))' % (c.location.z, ph), prop='location', passo=root)
    drv(obs['collo'], 0, 'p*0.18*sin(2*(%s))-(1-p)*1.0*max(0,sin(frame*0.22+%.3f)-0.2)' % (ph, fase), passo=root)
    drv(obs['collo'], 2, '(1-p)*0.4*sin(frame*0.05+%.3f)' % fase, passo=root)
    for s, o in (('sx', 0.0), ('dx', math.pi)):
        drv(obs['zampa_' + s], 0, 'p*0.5*sin(%s+%.3f)' % (ph, o), passo=root)
    return vg

def anima_acqua(root, obs, fase):
    c = obs['corpo']
    drv(c, 2, '%.3f+0.012*sin(frame*0.09+%.3f)' % (c.location.z, fase), prop='location')
    drv(c, 1, '0.03*sin(frame*0.07+%.3f)' % fase)
    drv(obs['collo'], 2, '0.35*sin(frame*0.017+%.3f)' % fase)
    drv(obs['collo'], 0, '-0.9*max(0,sin(frame*0.012+%.3f)-0.7)' % (fase * 1.9))
    return 0.22 * VELOCITA_ANIMALI

def anima_gabbiano(root, obs, fase, vola):
    c = obs['corpo']
    if vola:
        drv(obs['ala_sx'], 1, '0.55*sin(frame*0.32+%.3f)' % fase)
        drv(obs['ala_dx'], 1, '-0.55*sin(frame*0.32+%.3f)' % fase)
        drv(c, 2, '%.3f+0.08*sin(frame*0.32+%.3f)' % (c.location.z, fase + 1.2), prop='location')
        return 9.0
    vg = 0.4 * VELOCITA_ANIMALI
    ph = 'frame*%.4f+%.3f' % (_w(vg, 0.11, 0.5), fase)
    drv(obs['collo'], 2, '0.5*sin(frame*0.03+%.3f)' % fase)
    for s, o in (('sx', 0.0), ('dx', math.pi)):
        drv(obs['zampa_' + s], 0, 'p*0.5*sin(%s+%.3f)' % (ph, o), passo=root)
    return vg

def anima_persona(root, obs, v, fase, guardia=False):
    A = 0.42; ph = 'frame*%.4f+%.3f' % (_w(v, 0.9, A), fase)
    b = obs['bacino']
    drv(b, 2, '%.3f+0.03*abs(sin(%s))' % (b.location.z, ph), prop='location')
    drv(b, 2, '0.07*sin(%s)' % ph)
    drv(obs['collo'], 2, '0.3*sin(frame*0.017+%.3f)' % (fase * 1.3))
    for s, o in (('sx', 0.0), ('dx', math.pi)):
        drv(obs['anca_' + s], 0, '%.3f*sin(%s+%.3f)' % (A, ph, o))
        drv(obs['ginocchio_' + s], 0, '-0.9*max(0,cos(%s+%.3f))' % (ph, o))
        if guardia and s == 'dx':
            obs['spalla_dx'].rotation_euler = (0.1, 0, 0); obs['gomito_dx'].rotation_euler = (-0.1, 0, 0)
            continue
        drv(obs['spalla_' + s], 0, '-%.3f*sin(%s+%.3f)' % (0.12 if guardia else 0.35, ph, o))
        drv(obs['gomito_' + s], 0, '0.25+0.2*max(0,sin(%s+%.3f))' % (ph, o))

# --------------------------------------------------------------- mare, rendering, schermo
def onde():
    mare = next((o for o in bpy.data.objects if o.name.startswith('Mare')), None)
    if mare is None:
        return
    em = bpy.data.objects.new('Onde_movimento', None); collezione('Kit_Luci').objects.link(em)
    drv(em, 0, 'frame*0.05', prop='location')
    tex = bpy.data.textures.get('Onde') or bpy.data.textures.new('Onde', 'CLOUDS'); tex.noise_scale = 5.0
    m = mare.modifiers.new('Onde', 'DISPLACE'); m.texture = tex; m.strength = 0.18; m.mid_level = 0.5
    m.texture_coords = 'OBJECT'; m.texture_coords_object = em

def rendering(ftot):
    r = SC.render
    for eng in (('BLENDER_EEVEE_NEXT', 'BLENDER_EEVEE') if QUALITA == 'prova' else ('CYCLES',)):
        try: r.engine = eng; break
        except Exception: pass
    r.fps = FPS
    r.resolution_x, r.resolution_y = (1920, 1080) if FORMATO == '16:9' else (1080, 1920)
    r.resolution_percentage = 100; r.image_settings.file_format = 'PNG'; r.filepath = '//render/'
    for obj, attr, val in ((SC.view_settings, 'view_transform', 'AgX'), (r, 'use_motion_blur', True), (SC.view_settings, 'exposure', ESPOSIZIONE)):
        try: setattr(obj, attr, val)
        except Exception: pass
    for lk in (CONTRASTO, CONTRASTO.replace('AgX - ', ''), 'None'):
        try:
            SC.view_settings.look = lk; break
        except Exception: pass
    if r.engine == 'CYCLES':
        SC.cycles.samples = 128; SC.cycles.use_denoising = True
    SC.frame_start = 1; SC.frame_end = ftot

TASSELLARE = ('Terreno', 'Alberi', 'Alberi_Nuovi', 'Alberi_Aree_Nuove', 'Alberi_Infittimento', 'Rocce', 'Rocce_Promontori', 'Siepi_e_Confini', 'Villaggio_Altopiano')

def tassella(ob, coll, lato=90.0):
    import numpy as np
    me = ob.data; npoly = len(me.polygons)
    if npoly < 20000 or ob.get('tassellato'):
        return 0
    nv = len(me.vertices)
    co = np.empty(nv * 3, np.float32); me.vertices.foreach_get('co', co); co = co.reshape(-1, 3)
    ls = np.empty(npoly, np.int32); lt = np.empty(npoly, np.int32)
    me.polygons.foreach_get('loop_start', ls); me.polygons.foreach_get('loop_total', lt)
    lv = np.empty(len(me.loops), np.int32); me.loops.foreach_get('vertex_index', lv)
    mi = np.empty(npoly, np.int32); me.polygons.foreach_get('material_index', mi)
    sm = np.empty(npoly, bool); me.polygons.foreach_get('use_smooth', sm)
    ce = np.empty(npoly * 3, np.float32); me.polygons.foreach_get('center', ce); ce = ce.reshape(-1, 3)
    tx = np.floor(ce[:, 0] / lato).astype(int); ty = np.floor(ce[:, 1] / lato).astype(int); n_ = 0
    for a, b_ in {(int(p), int(q)) for p, q in zip(tx, ty)}:
        sel = np.where((tx == a) & (ty == b_))[0]
        facce = [lv[ls[i]:ls[i] + lt[i]] for i in sel]
        usati = np.unique(np.concatenate(facce)); rm = np.full(nv, -1, np.int64); rm[usati] = np.arange(len(usati))
        nm = bpy.data.meshes.new('%s_%d_%d' % (ob.name, a, b_))
        nm.from_pydata(co[usati].tolist(), [], [rm[f].tolist() for f in facce])
        for m in me.materials:
            nm.materials.append(m)
        nm.polygons.foreach_set('material_index', mi[sel]); nm.polygons.foreach_set('use_smooth', sm[sel]); nm.update()
        o2 = bpy.data.objects.new(nm.name, nm); coll.objects.link(o2); o2.matrix_world = ob.matrix_world; n_ += 1
    ob['tassellato'] = True; ob.hide_viewport = True; ob.hide_render = True; ob.hide_set(True)
    return n_

def riquadri():
    ct = collezione('Kit_Riquadri')
    if RIQUADRI:
        tot = 0
        for ob in list(bpy.data.objects):
            if ob.type == 'MESH' and ob.name.split('.')[0] in TASSELLARE:
                try: tot += tassella(ob, ct)
                except Exception as e: log('Riquadri non creati per %s: %s' % (ob.name, e))
        log('Riquadri: %d creati (gli oggetti originali sono nascosti, non cancellati)' % tot)
    else:
        n_ = len(ct.objects)
        for ob in list(ct.objects):
            bpy.data.objects.remove(ob, do_unlink=True)
        for ob in bpy.data.objects:
            if ob.get('tassellato'):
                del ob['tassellato']; ob.hide_viewport = False; ob.hide_render = False; ob.hide_set(False)
        if n_:
            log('Riquadri rimossi (%d); oggetti originali di nuovo visibili' % n_)

PREF_NOMI = ('use_gravity', 'view_height', 'walk_speed', 'walk_speed_factor', 'jump_height', 'mouse_speed')
PREF_VALORI = (True, 1.7, 3.0, 4.0, 0.6, 0.7)

def preferenze():
    wn = bpy.context.preferences.inputs.walk_navigation
    salvate = SC.get('kit_preferenze_originali')
    if PREFERENZE_CAMMINATA:
        if not salvate:
            SC['kit_preferenze_originali'] = {k: getattr(wn, k) for k in PREF_NOMI}
        for k, v in zip(PREF_NOMI, PREF_VALORI):
            try: setattr(wn, k, v)
            except Exception: pass
        log('Preferenze della camminata impostate (valgono per tutti i progetti; i valori precedenti sono salvati nel file)')
    elif salvate:
        for k in PREF_NOMI:
            if k in salvate:
                try: setattr(wn, k, salvate[k])
                except Exception: pass
        del SC['kit_preferenze_originali']; log('Preferenze della camminata ripristinate ai valori precedenti')

def vista_schermo():
    n_ = 0
    for scr in bpy.data.screens:
        for area in scr.areas:
            if area.type != 'VIEW_3D':
                continue
            sp = area.spaces.active
            vals = ((sp, 'clip_start', 0.3), (sp, 'clip_end', 6000.0), (sp, 'lens', 26.0), (sp.shading, 'type', 'RENDERED'),
                    (sp.overlay, 'show_overlays', False), (sp, 'show_gizmo', False)) if MODALITA_SCHERMO else \
                   ((sp.overlay, 'show_overlays', True), (sp, 'show_gizmo', True), (sp.shading, 'type', 'SOLID'))
            for obj, attr, val in vals:
                try: setattr(obj, attr, val)
                except Exception: pass
            n_ += 1
    if MODALITA_SCHERMO:
        try: SC.eevee.taa_samples = 16
        except Exception: pass
    log('Vista %s applicata a %d finestre 3D' % ('per la registrazione' if MODALITA_SCHERMO else 'normale', n_))

# --------------------------------------------------------------- avvio
def animali_statici(nascondi):
    n_ = 0
    for ob in bpy.data.objects:
        if ob.type == 'MESH' and ob.name.split('.')[0] == 'Animali':
            ob.hide_viewport = nascondi; ob.hide_render = nascondi
            try: ob.hide_set(nascondi)
            except Exception: pass
            n_ += 1
    return n_

def main():
    LOG.clear(); modello(); bpy.context.view_layer.update(); pulisci()
    cc, ca, cn, cp, cl = (collezione(k) for k in KIT)
    migliora_materiali()
    mondo(); sole(cl); qualita_ombre()
    f = 1; prima = None
    for r in DATI['riprese'] + [DATI['sentiero']] + DATI.get('riprese_nuove', []):
        cam, f1 = ripresa(r, f, cc, cp); prima = prima or cam; f = f1 + 1
    ftot = f - 1; SC.camera = prima
    log('Camere: %d, %d fotogrammi (%.0f s)' % (len(DATI['riprese']) + 1 + len(DATI.get('riprese_nuove', [])), ftot, ftot / FPS))
    rnd = random.Random(11)
    n_p = 0
    if ABITANTI:
        vesti = ['npc_veste_%d' % i for i in range(8)]; brache = ['npc_brache_%d' % i for i in range(3)]
        pelli = ['npc_pelle_%d' % i for i in range(3)]; capelli = ['npc_capelli_%d' % i for i in range(4)]
        for nomi, cols in ((vesti, ((0.55, 0.2, 0.15), (0.2, 0.3, 0.55), (0.35, 0.45, 0.2), (0.7, 0.55, 0.25), (0.45, 0.35, 0.3), (0.62, 0.6, 0.55), (0.3, 0.22, 0.4), (0.25, 0.4, 0.42))),
                           (brache, ((0.25, 0.2, 0.15), (0.3, 0.3, 0.32), (0.35, 0.28, 0.2))), (pelli, ((0.86, 0.66, 0.52), (0.72, 0.52, 0.38), (0.55, 0.38, 0.26))),
                           (capelli, ((0.12, 0.08, 0.05), (0.35, 0.22, 0.1), (0.6, 0.5, 0.35), (0.3, 0.3, 0.3)))):
            for nm, c_ in zip(nomi, cols):
                materiale(nm, c_)
        materiale('npc_paglia', (0.85, 0.72, 0.38)); materiale('npc_panno', (0.3, 0.12, 0.1)); materiale('npc_divisa', (0.6, 0.12, 0.12))
        for ri, rt in enumerate(DATI['percorsi']):
            pts = [punto((x, z, 0.0, 'w')) for x, z in rt['punti']]
            cur = curva('Percorso_%02d' % ri, pts, cp, chiusa=True); L = lunghezza(pts)
            for k in range(rt['persone']):
                i = n_p; v = (1.05 + 0.1 * (i % 4)) * VELOCITA_PERSONE
                gonna = (i % 5) in (1, 3); cap = 'npc_paglia' if i % 5 == 0 else ('npc_panno' if i % 5 == 2 else None)
                chiave = 'persona' + ('_gonna' if gonna else '') + ('_cappello' if cap else '')
                mappa = {'VESTE': vesti[i % 8], 'BRACHE': brache[i % 3], 'PELLE': pelli[i % 3], 'CAPELLI': capelli[i % 4], 'CAPPELLO': cap or 'npc_paglia'}
                root, obs = rig('Persona_%02d' % i, chiave, mappa, ca)
                anima_persona(root, obs, v, i * 1.3)
                cammina(root, cur, L, v, (k / rt['persone']) + 0.37 * ri % 1.0, ftot); n_p += 1
        for gi, g in enumerate(DATI['guardie']):
            pts = [punto(p) for p in g]; cur = curva('Ronda_%d' % gi, pts, cp, chiusa=True)
            root, obs = rig('Guardia_%d' % gi, 'guardia', {'VESTE': 'npc_divisa', 'BRACHE': brache[1], 'PELLE': pelli[gi % 3], 'CAPELLI': capelli[0]}, ca)
            anima_persona(root, obs, 0.9 * VELOCITA_PERSONE, gi * 2.0, guardia=True)
            cammina(root, cur, lunghezza(pts), 0.9 * VELOCITA_PERSONE, gi * 0.4, ftot); n_p += 1
        log('Persone: %d su %d percorsi + ronde sulle mura' % (n_p, len(DATI['percorsi'])))
    n_a = 0; soste = 0
    if ANIMALI:
        nascosti = animali_statici(True)
        for i, a in enumerate(DATI['animali']):
            sp = a['sp']; nome = 'Animale_%03d_%s' % (i, sp); fase = i * 0.77
            root, obs = rig(nome, a['m'], {'CORPO': a['c'], 'ZAMPE': a['c2']}, cn)
            if sp in ANDATURA: vel = anima_quadrupede(root, obs, sp, fase)
            elif sp == 'chicken': vel = anima_gallina(root, obs, fase)
            elif sp in ('duck', 'swan'): vel = anima_acqua(root, obs, fase)
            else: vel = anima_gabbiano(root, obs, fase, a.get('vola', False))
            fisso = a.get('ass', False)
            pts = [punto((x, z, a['y'], 'a')) if fisso else punto((x, z, 0.0, 'w')) for x, z in a['anello']]
            cur = curva(nome + '_giro', pts, cp, chiusa=True); L = lunghezza(pts)
            if sp in ('duck', 'swan') or a.get('vola'):
                cammina(root, cur, L, vel, (i * 0.137) % 1.0, ftot)
            elif sp == 'dog':
                pascolo(root, cur, L, vel, (i * 0.137) % 1.0, ftot, rnd, muovi=(3.0, 8.0), ferma=(2.0, 6.0)); soste += 1
            elif sp in ('chicken', 'seagull'):
                pascolo(root, cur, L, vel, (i * 0.137) % 1.0, ftot, rnd, muovi=(0.8, 2.5), ferma=(1.0, 4.0)); soste += 1
            else:
                pascolo(root, cur, L, vel, (i * 0.137) % 1.0, ftot, rnd); soste += 1
            n_a += 1
        log('Animali: %d articolati, tutti in movimento (%d alternano cammino e soste per brucare/beccare); %d oggetti di animali fermi dell\'OBJ nascosti' % (n_a, soste, nascosti))
    else:
        animali_statici(False)
        log('Animali: quelli fermi dell\'OBJ restano visibili (ANIMALI = False)')
    if UCCELLI:
        cx, cz = DATI['centro_fortezza']
        for i in range(6):
            root, obs = rig('Uccello_%d' % i, 'seagull_vola', {}, ca)
            anima_gabbiano(root, obs, i * 1.1, True)
            R = 60 + 10 * i; h = 58 + 4 * (i % 3)
            pts = [B(cx + R * math.cos(t), h + 4 * math.sin(3 * t), cz + R * math.sin(t)) for t in [k * 2 * math.pi / 12 for k in range(12)]]
            cammina(root, curva('Uccello_%d_volo' % i, pts, cp, chiusa=True), 2 * math.pi * R, 9.0, i / 6.0, ftot)
    if ONDE:
        onde()
    rendering(ftot); riquadri(); preferenze(); vista_schermo()
    SC.frame_set(1)
    log('Kit di ripresa %s pronto.' % VERSIONE_KIT)
    try: bpy.context.window_manager.clipboard = '\n'.join(LOG)
    except Exception: pass

try:
    main()
except Exception:
    log('ERRORE:\n' + traceback.format_exc())
    try: bpy.context.window_manager.clipboard = '\n'.join(LOG)
    except Exception: pass
    raise
